using System;using System.Text;using System.Reflection;using System.Collections.Generic;using System.IO;using System.Globalization;
class EncodingSurface{
 static string TypeName(Type t){if(t.IsByRef)return TypeName(t.GetElementType())+"&";if(t.IsPointer)return TypeName(t.GetElementType())+"*";return t.FullName??t.ToString();}
 static string Parameters(ParameterInfo[] args){var r=new List<string>();foreach(var p in args)r.Add((p.IsOut?"out ":"")+TypeName(p.ParameterType)+" "+p.Name);return string.Join(", ",r.ToArray());}
 static void Main(string[] args){var rows=new List<string>();foreach(var t in new[]{typeof(Encoding),typeof(ASCIIEncoding),typeof(UnicodeEncoding),typeof(UTF8Encoding),typeof(UTF32Encoding),typeof(UTF7Encoding),typeof(Encoder),typeof(Decoder),typeof(EncoderFallback),typeof(DecoderFallback),typeof(EncoderFallbackBuffer),typeof(DecoderFallbackBuffer)}){
 foreach(var c in t.GetConstructors(BindingFlags.Public|BindingFlags.Instance))rows.Add(t.FullName+"\tconstructor\t"+t.Name+"("+Parameters(c.GetParameters())+")");
 foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly))if(!m.IsSpecialName)rows.Add(t.FullName+"\t"+(m.IsStatic?"static ":"")+"method\t"+TypeName(m.ReturnType)+" "+m.Name+"("+Parameters(m.GetParameters())+")");
 foreach(var p in t.GetProperties(BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly))rows.Add(t.FullName+"\tproperty\t"+TypeName(p.PropertyType)+" "+p.Name+" "+(p.CanRead?"get;":"")+(p.CanWrite?"set;":""));
 }rows.Sort(StringComparer.Ordinal);File.WriteAllLines(args[0],rows,new UTF8Encoding(false));Console.WriteLine(rows.Count+" public Encoding/Encoder/Decoder/fallback declarations (positive inventory, not native coverage)");
 var pages=Encoding.GetEncodings();Array.Sort(pages,delegate(EncodingInfo a,EncodingInfo b){return a.CodePage.CompareTo(b.CodePage);});using(var w=new StreamWriter(args[1],false,new UTF8Encoding(false))){w.WriteLine("# code_page\tWebName\tBodyName\tHeaderName\tWindowsCodePage\tIsSingleByte\tBrowserDisplay\tBrowserSave\tMailDisplay\tMailSave\tIsReadOnly\tEnglishName\tRussianName");foreach(var p in pages){var e=p.GetEncoding();System.Threading.Thread.CurrentThread.CurrentUICulture=CultureInfo.GetCultureInfo("en-US");string en=e.EncodingName;System.Threading.Thread.CurrentThread.CurrentUICulture=CultureInfo.GetCultureInfo("ru-RU");string ru=e.EncodingName;w.WriteLine(e.CodePage+"\t"+e.WebName+"\t"+e.BodyName+"\t"+e.HeaderName+"\t"+e.WindowsCodePage+"\t"+e.IsSingleByte+"\t"+e.IsBrowserDisplay+"\t"+e.IsBrowserSave+"\t"+e.IsMailNewsDisplay+"\t"+e.IsMailNewsSave+"\t"+e.IsReadOnly+"\t"+en+"\t"+ru);}}Console.WriteLine("Default code page="+Encoding.Default.CodePage);
 }
}